    INF = 99
    L = []
    cur = 0
    for i in range(N):
        L.append(X[i] - cur)
        cur = X[i]
    dp = [[[INF] * (H + 1) for _ in range(H + 1)] for _ in range(N + 1)]
    P.append(0)
    F.append(0)
    for i in range(H + 1):
        dp[0][H][i] = 0

    for i in range(N):
        for j in range(H + 1):
            for k in range(H + 1):
                if dp[i][j][k] == INF:
                    continue
                if j - L[i] < 0 or k + L[i] > H:
                    continue
                # 往路で利用するとき
                dp[i + 1][min(j - L[i] + F[i], H)][k + L[i]] = min(dp[i][j][k] + P[i], dp[i + 1][min(j - L[i] + F[i], H)][k + L[i]])
                # 復路で利用するとき
                if k + L[i] == H:
                    for l in range(F[i] + 1):
                        if 0 <= k + L[i] - l:
                            dp[i + 1][j - L[i]][k + L[i] - l] = min(dp[i][j][k] + P[i], dp[i + 1][j - L[i]][k + L[i] - l])
                else:
